// Captain self-police: parse every .feature with @cucumber/gherkin and
// cross-check every watchbill.json reference against the parsed scenario titles.
const fs = require('fs');
const path = require('path');
const { Parser, AstBuilder, GherkinClassicTokenMatcher } = require('@cucumber/gherkin');
const { IdGenerator } = require('@cucumber/messages');

const root = process.argv[2];
const featuresDir = path.join(root, 'features');
const watchbillPath = path.join(root, 'watchbill.json');

let fail = 0;
const log = (m) => { console.log(m); };
const err = (m) => { console.error('FAIL: ' + m); fail++; };

// 1. watchbill.json is valid JSON and well-shaped.
let watchbill;
try {
  const raw = fs.readFileSync(watchbillPath, 'utf8');
  watchbill = JSON.parse(raw);
} catch (e) {
  err('watchbill.json is not valid JSON: ' + e.message);
  process.exit(fail);
}
const watchKeys = Object.keys(watchbill).sort();
const expected = Array.from({ length: watchKeys.length }, (_, i) => 'watch' + (i + 1));
if (JSON.stringify(watchKeys) !== JSON.stringify(expected)) {
  err('watchbill keys are not watch1..watchN in order: ' + JSON.stringify(watchKeys));
}
for (const k of watchKeys) {
  const w = watchbill[k];
  if (!w || !Array.isArray(w.scenarios)) {
    err(k + '.scenarios is not an array');
  }
}

// 2. Parse every feature and collect scenario titles (incl. Scenario Outline titles).
const parser = new Parser(new AstBuilder(IdGenerator.incrementing()));
parser.stopAtFirstError = false;
const matcher = new GherkinClassicTokenMatcher();

const featureFiles = fs.readdirSync(featuresDir)
  .filter((f) => f.endsWith('.feature'))
  .sort();

const titles = {}; // rel path -> Set(title)
const rel = (f) => path.relative(root, path.join(featuresDir, f)).replace(/\\/g, '/');

for (const f of featureFiles) {
  const src = fs.readFileSync(path.join(featuresDir, f), 'utf8');
  const rp = rel(f);
  titles[rp] = new Set();
  let ast;
  try {
    ast = parser.parse(src, matcher);
  } catch (e) {
    err(rp + ' failed to parse: ' + e.message);
    continue;
  }
  for (const child of ast.feature.children) {
    const sc = child.scenario;
    if (sc && sc.name) titles[rp].add(sc.name);
  }
  log('parsed ' + rp + ' (' + titles[rp].size + ' scenario titles)');
}

// 3. Cross-check every watchbill reference.
let refCount = 0;
const seen = new Set();
for (const k of watchKeys) {
  const arr = Array.isArray(watchbill[k].scenarios) ? watchbill[k].scenarios : [];
  for (const ref of arr) {
    refCount++;
    const idx = ref.indexOf(':');
    if (idx < 0) { err('reference without colon: ' + ref); continue; }
    const file = ref.slice(0, idx);
    const name = ref.slice(idx + 1);
    if (!titles[file]) { err('reference to missing feature file: ' + file); continue; }
    if (!titles[file].has(name)) {
      err('scenario name not found in ' + file + ': ' + JSON.stringify(name));
      log('  available titles in ' + file + ':');
      for (const t of [...titles[file]].sort()) log('    - ' + t);
    }
    seen.add(ref);
  }
}

log('---');
log('feature files: ' + featureFiles.length);
log('scenario titles parsed: ' + Object.values(titles).reduce((n, s) => n + s.size, 0));
log('watchbill references: ' + refCount + ' (unique ' + seen.size + ')');
console.log(fail === 0 ? 'POLICE: PASS' : 'POLICE: FAIL (' + fail + ')');
process.exit(fail === 0 ? 0 : 1);

