// Captain self-police: parse every .feature with @cucumber/gherkin (v41 API) and
// cross-check every watchbill.json reference against the parsed scenario titles.
// Handles Background, flat Scenario, Scenario Outline, and Rule-nested scenarios.
const fs = require('fs');
const path = require('path');
const { Parser, AstBuilder, GherkinClassicTokenMatcher } = require('@cucumber/gherkin');
const { IdGenerator } = require('@cucumber/messages');

const root = process.cwd();
const featuresDir = path.join(root, 'features');
const watchbillPath = path.join(root, 'watchbill.json');

let fail = 0;
const log = (m) => { console.log(m); };
const err = (m) => { console.error('FAIL: ' + m); fail++; };

let watchbill;
try {
  watchbill = JSON.parse(fs.readFileSync(watchbillPath, 'utf8'));
} catch (e) {
  err('watchbill.json is not valid JSON: ' + e.message);
  process.exit(fail);
}
const watchKeys = Object.keys(watchbill).sort();
const expected = Array.from({ length: watchKeys.length }, (_, i) => 'watch' + (i + 1));
if (JSON.stringify(watchKeys) !== JSON.stringify(expected)) {
  err('watchbill keys are not watch1..watchN in order: ' + JSON.stringify(watchKeys));
}
for (const k of watchKeys) {
  if (!watchbill[k] || !Array.isArray(watchbill[k].scenarios)) err(k + '.scenarios is not an array');
}

const parser = new Parser(new AstBuilder(IdGenerator.incrementing()), new GherkinClassicTokenMatcher('en'));

const collectScenarios = (children, set) => {
  for (const child of children) {
    if (child.scenario && child.scenario.name) set.add(child.scenario.name);
    if (child.rule && Array.isArray(child.rule.children)) collectScenarios(child.rule.children, set);
  }
};

const featureFiles = fs.readdirSync(featuresDir).filter((f) => f.endsWith('.feature')).sort();
const titles = {};
const rel = (f) => path.relative(root, path.join(featuresDir, f)).replace(/\\/g, '/');

for (const f of featureFiles) {
  const rp = rel(f);
  titles[rp] = new Set();
  let ast;
  try {
    ast = parser.parse(fs.readFileSync(path.join(featuresDir, f), 'utf8'));
  } catch (e) {
    err(rp + ' failed to parse: ' + e.message);
    continue;
  }
  collectScenarios(ast.feature.children, titles[rp]);
  log('parsed ' + rp + ' (' + titles[rp].size + ' scenario titles)');
}

let refCount = 0;
const seen = new Set();
for (const k of watchKeys) {
  const arr = Array.isArray(watchbill[k].scenarios) ? watchbill[k].scenarios : [];
  for (const ref of arr) {
    refCount++;
